        'ortodoncia.faq.a2': 'La duración varía según la complejidad de cada caso. Por lo general, los tratamientos oscilan entre los 12 y 24 meses. Gracias a la Ortodoncia Digital y sistemas como Invisalign, en muchos casos logramos reducir estos tiempos significativamente.',
