        'ortodoncia.faq.q4': '¿Se puede comer de todo con Invisalign?',
        'ortodoncia.faq.a4': '¡Sí! Esa es una de sus grandes ventajas. Al ser alineadores removibles, te los quitas para comer, por lo que no tienes restricciones alimentarias y puedes mantener una higiene dental perfecta.',
