        'ortodoncia.faq.a5': 'Los retenedores son fundamentales para mantener los resultados. Una vez alineados los dientes con el tratamiento, estos tienen "memoria" y tienden a volver a su posición original. Los retenedores aseguran que tu sonrisa se mantenga perfecta de por vida.',
