        'endodoncia.faq.badge': 'FAQ',
        'endodoncia.faq.title': 'Dudas frecuentes',
        'endodoncia.faq.q1.q': '¿Es doloroso hacerse una endodoncia?',
        'endodoncia.faq.q1.a': 'No. Gracias al uso de anestesia local avanzada y técnicas modernas, el paciente no siente dolor durante el procedimiento. El objetivo de la endodoncia es, precisamente, eliminar el dolor causado por la infección del nervio.',
        'endodoncia.faq.q2.q': '¿Cuánto tiempo dura el tratamiento?',
        'endodoncia.faq.q2.a': 'Generalmente se realiza en una sola sesión de entre 60 y 90 minutos, dependiendo de la complejidad del diente y el número de conductos. En casos de infecciones muy severas, puede requerir una segunda cita.',
        'endodoncia.faq.q3.q': '¿Qué cuidados debo tener después?',
        'endodoncia.faq.q3.a': 'Es normal sentir una ligera sensibilidad al masticar los primeros días. Recomendamos no comer cosas muy duras hasta que el diente sea reconstruido definitivamente, ya que tras la endodoncia la pieza se vuelve algo más frágil.',
        'endodoncia.faq.q4.q': '¿Por qué es mejor una endodoncia que extraer el diente?',
        'endodoncia.faq.q4.a': 'Nada funciona tan bien como tu propio diente natural. Mantener tu pieza evita que los dientes adyacentes se muevan, previene la pérdida de hueso y es estéticamente más natural.',
        'endodoncia.faq.q5.q': '¿Un diente con endodoncia puede tener caries?',
        'endodoncia.faq.q5.a': 'Sí. Aunque el diente ya no tenga nervio (sensibilidad), la estructura externa sigue siendo susceptible a las bacterias. Por ello, es fundamental mantener una buena higiene y acudir a las revisiones periódicas.',
