        'home.presentation.title': 'Raum + Technologie + Menschen',
        'home.presentation.lead': 'In der Clínica Koral sind wir nicht nur eine Zahnklinik. Wir sind ein team, das liebt, was es tut.',
        'home.presentation.desc': 'Unser team von Zahnärzten besteht aus Spezialisten mit exklusiver Hingabe an ihr Fachgebiet. Dies bedeutet, dass Sie bei Ihrer Zahnbehandlung all die Jahre Erfahrung und aktualisierte Ausbildung einer Person erhalten, die sich leidenschaftlich für ihre Spezialität einsetzt.',
