        'home.presentation.badge': 'De Kliniek',
        'home.presentation.title': 'Ruimte + Technologie + Mensen',
        'home.presentation.lead': 'Bij Clínica Koral zijn we niet zomaar een tandkliniek. We zijn een team dat houdt van wat we doen.',
        'home.presentation.desc': 'Ons team van tandartsen bestaat uit specialisten met exclusieve toewijding aan hun vakgebied. Dit betekent dat u bij uw tandheelkundige behandeling alle jaren ervaring en geactualiseerde training ontvangt van een persoon die gepassioneerd is over zijn specialiteit.',
