        'treatments.desc.main': 'Notre méthodologie combine l\'expérience avec les techniques plus avancées.',
        'treatments.more': 'En savoir plus',
        'treatments.ortodoncia.title': 'ORTHODONTIE ET ATM',
        'treatments.ortodoncia.desc': 'L\'orthodontie améliore la position de vos dents, en accordant une attention particulière à leur bon fonctionnement.',
