        'treatments.endodoncia.desc': 'Notre mission est de prolonger la vie de votre dent pendant de nombreuses années en éliminating la douleur.',
        'treatments.estetica.title': 'ESTHÉTIQUE DENTAIRE',
        'treatments.estetica.desc': 'Facettes dentaires, conception numérique du sourire, remodelage des gencives et blanchiment.',
        'treatments.rehabilitacion.title': 'RÉHABILITATION ORALE',
        'treatments.rehabilitacion.desc': 'Profitez pleinement de votre bouche de manière intégrale, en restaurant sa fonction, son apparence et sa santé.',
        'treatments.periodoncia.title': 'PARODONTOLOGIE',
        'treatments.periodoncia.desc': 'Santé de vos gencives et de votre os. Examens périodiques et hygiène professionnelle.',
        'treatments.cirugia.title': 'CHIRURGIE ORALE',
        'treatments.cirugia.desc': 'Extraction des dents de sagesse, des kystes et chirurgie régénératrice avec 10 ans d\'expérience.',
