        'appointment.facilities': 'Installations',
        'appointment.title.main': 'Votre santé n\'attend pas',
        'appointment.desc.main': 'Nous voulons que le coût de votre traitement ne soit pas un obstacle. À la Clínica Koral, nous concevons des plans sur mesure pour vous.',
        'appointment.financing.title': '0% d\'intérêt',
        'appointment.financing.desc': 'Financement direct sans intérêt pour la plupart des traitements.',
        'appointment.free.title': 'Rendez-vous gratuit',
        'appointment.free.desc': 'Votre première évaluation est entièrement gratuite et sans engagement.',
        'appointment.request.title': 'Demandez votre rendez-vous',
