        'odontopediatria.stages.3.p1': 'Établir une relation de confiance',
        'odontopediatria.stages.3.p2': 'Détection précoce des caries infantiles',
        'odontopediatria.stages.3.p3': 'Contrôle des sucres cachés dans l\'alimentation',
